/// Found by name by `AssistantSpotlight` in the runtime; apps register nothing.
@objc(AssistantActionsAppSpotlight)
public final class AssistantActionsAppSpotlight: NSObject, AssistantSpotlightIndexer {
  public func index(collection: String, removedIDs: [String], clearFirst: Bool) async throws {
    guard #available(iOS 18.0, macOS 15.0, *) else { return }
    switch collection {
    case "Recipe":
      try await Self.update(
        AssistantSnapshot.records("Recipe").map(RecipeEntity.init(record:)),
        removed: removedIDs, clearFirst: clearFirst)
    case "TaskItem":
      if #available(iOS 27.0, macOS 27.0, *) {
        try await Self.update(
          AssistantSnapshot.records("TaskItem").map(TaskItemEntity.init(record:)),
          removed: removedIDs, clearFirst: clearFirst)
      }
    case "MemoryItem":
      if #available(iOS 27.0, macOS 27.0, *) {
        try await Self.update(
          AssistantSnapshot.records("MemoryItem").map(MemoryItemEntity.init(record:)),
          removed: removedIDs, clearFirst: clearFirst)
      }
    case "JournalItem":
      if #available(iOS 26.0, macOS 26.0, *) {
        try await Self.update(
          AssistantSnapshot.records("JournalItem").map(JournalItemEntity.init(record:)),
          removed: removedIDs, clearFirst: clearFirst)
      }
    case "Countdown":
      if #available(iOS 27.0, macOS 27.0, *) {
        try await Self.update(
          AssistantSnapshot.records("Countdown").map(CountdownEntity.init(record:)),
          removed: removedIDs, clearFirst: clearFirst)
      }
    case "DocItem":
      try await Self.updateFiles(
        AssistantSnapshot.records("DocItem").map(DocItemEntity.init(record:)),
        removed: removedIDs, clearFirst: clearFirst)
    default:
      break
    }
  }

  @available(iOS 18.0, macOS 15.0, *)
  private static func update<E: IndexedEntity>(_ entities: [E], removed: [String], clearFirst: Bool) async throws
  where E.ID == String {
    let index = CSSearchableIndex.default()
    if clearFirst {
      try await index.deleteAppEntities(ofType: E.self)
    } else if !removed.isEmpty {
      try await index.deleteAppEntities(identifiedBy: removed, ofType: E.self)
    }
    if !entities.isEmpty {
      try await index.indexAppEntities(entities)
    }
  }
  @available(iOS 18.0, macOS 15.0, *)
  private static func updateFiles<E: IndexedEntity>(_ entities: [E], removed: [String], clearFirst: Bool) async throws
  where E.ID == FileEntityIdentifier {
    let index = CSSearchableIndex.default()
    if clearFirst {
      try await index.deleteAppEntities(ofType: E.self)
    } else if !removed.isEmpty {
      try await index.deleteAppEntities(identifiedBy: removed.map(AssistantFileIDs.identifier), ofType: E.self)
    }
    if !entities.isEmpty {
      try await index.indexAppEntities(entities)
    }
  }
}

/// An `@EntityImage()` that is a local file (an absolute path or a `file:`
/// URL), read here in the app's process, so Siri, Shortcuts and Spotlight,
/// which draw in other processes, can show a file in the app's sandbox.
private func assistantImageData(_ value: String?) -> Data? {
  guard let value, !value.isEmpty else { return nil }
  guard let url = value.hasPrefix("/") ? URL(fileURLWithPath: value) : URL(string: value), url.isFileURL else {
    return nil
  }
  return try? Data(contentsOf: url)
}

/// What Siri and Shortcuts show with an item: its `@EntityImage()` (a local
/// file's bytes, or a remote URL the system loads), else the type's SF Symbol.
private func assistantDisplayImage(_ value: String?, systemName: String?) -> DisplayRepresentation.Image? {
  if let data = assistantImageData(value) { return .init(data: data) }
  if let value, let url = URL(string: value), ["https", "http"].contains(url.scheme?.lowercased() ?? "") {
    return .init(url: url)
  }
  return systemName.map { .init(systemName: $0) }
}

