  public init(_ card: AssistantCard?) {
    self.card = card?.json ?? ""
    id = UUID().uuidString
  }

  @MainActor
  public func perform() async throws -> some IntentResult & ShowsSnippetView {
    let card = AssistantCardStore.card(id, initial: card)
